---@param player SBasePlayer | CBasePlayer
---@param cfg PayActivityConfigData
function IPayActivity:ctor(player, cfg)
    self.activityId = cfg.id
    self.player = player
    self.cfg = cfg
    self.info = PayActivityInfo.new(player.userId .. ":pay_activity_" .. self.activityId)
    self.c2sFuncs = {}
    self:initDataInfo()
end

function IPayActivity:registerC2SFunc(name)
    self.c2sFuncs[name] = true
end

function IPayActivity:isC2SFuncRegister(name)
    return self.c2sFuncs[name]
end

function IPayActivity:initInfoKey(key, defValue)
