function IPayActivity:setSaveDBData(data)
    for key, value in pairs(data) do
        self.info:setValue(key, value)
    end
    if isServer then
        self.info.change = false
        self.info.syncs = {}
    end
end

function IPayActivity:getSaveDBData()
    return self.info:getSaveDBData()
end

---@private
function IPayActivity:start()
    self:onStart()
    if isClient then
        self:tryShowEntryUI()
        self:tryShowLoginUI()
    end
end

---@private
function IPayActivity:stop()
    self:unregisterAllEvent()
    self:onStop()
    if isClient then
        local cfg = PayActivityConfig:getLoginUICfgById(self.activityId)
        if not cfg then
            return
        end
        UIHelper.hideGameGUILayout(cfg.layout)
    end
end

function IPayActivity:runServerFunc(name, ...)
    if isClient then
        PayActivityPkSender:runPayActivityFunc(self.activityId, name, { ... })
    else
        local func = self[name]
        if func then
            func(self, ...)
        end
    end
end

function IPayActivity:runClientFunc(name, ...)
    if isClient then
        local func = self[name]
        if func then
            func(self, ...)
        end
    else
        PayActivityPkSender:runPayActivityFunc(self.player, self.activityId, name, { ... })
    end
end

