end

function IPayActivity:interceptLoginUI()
    return false
end

---@private
function IPayActivity:tryShowLoginUI()
    if not isClient then
        return
    end
    local cfg = PayActivityConfig:getLoginUICfgById(self.activityId)
    if not cfg then
        return
    end
    if self:interceptLoginUI() then
        return
    end
    UIHelper.showGameGUILayout(cfg.layout, self, cfg.params)
end

function IPayActivity:tryShowActivityUI()
    if not isClient or self.cfg.activityUIName == "#" then
        return
    end
    UIHelper.showGameGUILayout(self.cfg.activityUIName, self)
    ReportEvent.reportEvent(Game:getPlatformUserId(), "limited_giftpack_click")
end

