end

function IPayActivity:canReward(rewardIds, doNotShowTips)
    if type(rewardIds) == "number" then
        rewardIds = { rewardIds }
    end
    local result = {}
    for _, rewardId in pairs(rewardIds) do
        local cfg = PayActivityRewardConfig:getCfgById(rewardId)
        if cfg then
            table.insert(result, {
                type = cfg.type,
                rewardId = cfg.realId,
                count = cfg.count,
            })
        end
    end
    if next(result) == nil then
        return true
    end
    return Events.CommonCanReceiveRewardEvent:invoke(self.player, result, doNotShowTips)
end

---@param rewardIds number | number[]
function IPayActivity:doReward(rewardIds, ui, params)
    if isClient then
        return
    end
    if type(rewardIds) == "number" then
        rewardIds = { rewardIds }
    end
    local result = {}
    for _, rewardId in pairs(rewardIds) do
        local cfg = PayActivityRewardConfig:getCfgById(rewardId)
        if cfg then
            local count = cfg.count
            if params then
                if params.counts and params.counts[rewardId] then
                    count = count * params.counts[rewardId]
                end
            end
            Events.CommonReceiveRewardEvent:invoke(self.player, cfg.type, cfg.realId, count, cfg.time)
            table.insert(result, rewardId)
        else
            LogUtil.logError("++++++++++++++++++++++ IPayActivity:doReward,no reward in cfg csv: ", rewardId)
        end
    end
    if next(result) == nil then
        return
    end
    if not (params and params.doNotShowResult) then
        PayActivityPkSender:sendGetPayActivityReward(self.player, result, ui, params)
    end
    return result
end

function IPayActivity:updateRedDot(show)
    if isServer then
        return
    end
    Plugins.CallTargetPluginFunc("red_dot", "resetRedDotState", "pay_activity:" .. self.cfg.id, show and 1 or 0)
end

function IPayActivity:__tostring()
    return tostring(self.info)
end

function IPayActivity:requestCheckPlayerHasRewardItem(rewardIdList, callBack)
    if isClient then
        PlayerManager:getClientPlayer():sendPacket({
            pid = "requestCheckPlayerHasRewardItem",
            rewardIdList = rewardIdList,
            activityId = self.activityId
        }, function(ret)
            if ret then
                self.hasRewardInf = TableUtil.copyTable(ret)
            end
            if callBack then
                callBack(ret)
            end
        end)
    end
end

function IPayActivity:checkPlayerHasRewardItem(rewardList, playerId)
    if isClient then
        self:runServerFunc("checkPlayerHasRewardItem", rewardList, playerId)
    else
        local player = PlayerManager:getPlayerByUserId(playerId)
        if player and player.checkHasRewardItem and rewardList then
            return player:checkHasRewardItem(rewardList)
        end
        return {}
    end
end

function IPayActivity:checkPlayerCanAddReward(playerId, itemId, count)
    if isClient then
        return
    else
        local player = PlayerManager:getPlayerByUserId(playerId)
        if player and player.canAddPayActivityReward and itemId and count then
            return player:canAddPayActivityReward(itemId, count)
        end
        return true
    end
end

